SELECT '=== residual -07:00 (all should be 0) ===' x;
SELECT (SELECT COUNT(*) FROM ai_tasks WHERE created_at LIKE '%-07:00') AS c0, (SELECT COUNT(*) FROM ai_tasks WHERE updated_at LIKE '%-07:00') AS c1, (SELECT COUNT(*) FROM asset_snapshots WHERE created_at LIKE '%-07:00') AS c2, (SELECT COUNT(*) FROM assets WHERE created_at LIKE '%-07:00') AS c3, (SELECT COUNT(*) FROM assets WHERE last_inspected_at LIKE '%-07:00') AS c4, (SELECT COUNT(*) FROM assets WHERE updated_at LIKE '%-07:00') AS c5;
