SELECT (SELECT COUNT(*) FROM field_observations WHERE created_at LIKE '%-07:00') AS c18, (SELECT COUNT(*) FROM login_sessions WHERE created_at LIKE '%-07:00') AS c19, (SELECT COUNT(*) FROM login_sessions WHERE expire_at LIKE '%-07:00') AS c20, (SELECT COUNT(*) FROM login_sessions WHERE updated_at LIKE '%-07:00') AS c21, (SELECT COUNT(*) FROM management_ai_reports WHERE expires_at LIKE '%-07:00') AS c22, (SELECT COUNT(*) FROM management_ai_reports WHERE generated_at LIKE '%-07:00') AS c23;
