SELECT (SELECT COUNT(*) FROM schema_migrations WHERE applied_at LIKE '%-07:00') AS c30, (SELECT COUNT(*) FROM submission_idempotency WHERE created_at LIKE '%-07:00') AS c31, (SELECT COUNT(*) FROM submission_idempotency WHERE updated_at LIKE '%-07:00') AS c32, (SELECT COUNT(*) FROM users WHERE created_at LIKE '%-07:00') AS c33, (SELECT COUNT(*) FROM users WHERE last_login_at LIKE '%-07:00') AS c34, (SELECT COUNT(*) FROM users WHERE updated_at LIKE '%-07:00') AS c35;